import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const Auth = ({ onNavigate }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    password: '',
    confirmPassword: ''
  });
  const [errors, setErrors] = useState({});
  const [loading, setLoading] = useState(false);
  const [rememberMe, setRememberMe] = useState(false);

  const { login, register } = useAuth();
  const navigate = useNavigate();

  // Валидация формы
  const validateForm = () => {
    const newErrors = {};

    // Email validation
    if (!formData.email) {
      newErrors.email = 'Email обязателен';
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = 'Некорректный email';
    }

    // Password validation
    if (!formData.password) {
      newErrors.password = 'Пароль обязателен';
    } else if (formData.password.length < 6) {
      newErrors.password = 'Пароль должен быть не менее 6 символов';
    }

    // Registration specific validations
    if (!isLogin) {
      if (!formData.username) {
        newErrors.username = 'Имя пользователя обязательно';
      } else if (formData.username.length < 3) {
        newErrors.username = 'Имя должно быть не менее 3 символов';
      }

      if (formData.password !== formData.confirmPassword) {
        newErrors.confirmPassword = 'Пароли не совпадают';
      }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    setLoading(true);

    try {
      if (isLogin) {
        await login(formData.email, formData.password, rememberMe);
        alert('✅ Вход выполнен успешно!');
      } else {
        await register(formData.username, formData.email, formData.password);
        alert('🎉 Регистрация прошла успешно!');
      }

      // Перенаправление
      if (onNavigate && typeof onNavigate === 'function') {
        onNavigate('profile');
      } else {
        navigate('/profile');
      }

    } catch (error) {
      alert(`❌ ${error.message || 'Произошла ошибка'}`);
    } finally {
      setLoading(false);
    }
  };

  const switchMode = () => {
    setIsLogin(!isLogin);
    setFormData({
      username: '',
      email: '',
      password: '',
      confirmPassword: ''
    });
    setErrors({});
  };

  return (
    <div className="max-w-md mx-auto mt-8 p-8 bg-white rounded-lg shadow-xl">
      <h2 className="text-2xl font-serif font-bold text-center mb-6 text-gold-600">
        {isLogin ? 'Вход в аккаунт' : 'Создание аккаунта'}
      </h2>

      <form onSubmit={handleSubmit} className="space-y-4">
        {!isLogin && (
          <div>
            <label className="block text-sm font-medium mb-1 text-gray-700">
              Имя пользователя *
            </label>
            <input
              type="text"
              value={formData.username}
              onChange={(e) => setFormData({...formData, username: e.target.value})}
              className={`w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-gold-500 transition-colors ${
                errors.username ? 'border-red-500' : 'border-gray-300'
              }`}
              placeholder="Введите имя пользователя"
              disabled={loading}
            />
            {errors.username && (
              <p className="text-red-500 text-sm mt-1">{errors.username}</p>
            )}
          </div>
        )}

        <div>
          <label className="block text-sm font-medium mb-1 text-gray-700">
            Email *
          </label>
          <input
            type="email"
            value={formData.email}
            onChange={(e) => setFormData({...formData, email: e.target.value})}
            className={`w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-gold-500 transition-colors ${
              errors.email ? 'border-red-500' : 'border-gray-300'
            }`}
            placeholder="example@mail.com"
            disabled={loading}
          />
          {errors.email && (
            <p className="text-red-500 text-sm mt-1">{errors.email}</p>
          )}
        </div>

        <div>
          <label className="block text-sm font-medium mb-1 text-gray-700">
            Пароль *
          </label>
          <input
            type="password"
            value={formData.password}
            onChange={(e) => setFormData({...formData, password: e.target.value})}
            className={`w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-gold-500 transition-colors ${
              errors.password ? 'border-red-500' : 'border-gray-300'
            }`}
            placeholder="Не менее 6 символов"
            minLength="6"
            disabled={loading}
          />
          {errors.password && (
            <p className="text-red-500 text-sm mt-1">{errors.password}</p>
          )}
        </div>

        {!isLogin && (
          <div>
            <label className="block text-sm font-medium mb-1 text-gray-700">
              Подтвердите пароль *
            </label>
            <input
              type="password"
              value={formData.confirmPassword}
              onChange={(e) => setFormData({...formData, confirmPassword: e.target.value})}
              className={`w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-gold-500 transition-colors ${
                errors.confirmPassword ? 'border-red-500' : 'border-gray-300'
              }`}
              placeholder="Повторите пароль"
              minLength="6"
              disabled={loading}
            />
            {errors.confirmPassword && (
              <p className="text-red-500 text-sm mt-1">{errors.confirmPassword}</p>
            )}
          </div>
        )}

        {isLogin && (
          <div className="flex items-center">
            <input
              type="checkbox"
              id="rememberMe"
              checked={rememberMe}
              onChange={(e) => setRememberMe(e.target.checked)}
              className="h-4 w-4 text-gold-600 focus:ring-gold-500 border-gray-300 rounded"
              disabled={loading}
            />
            <label htmlFor="rememberMe" className="ml-2 block text-sm text-gray-700">
              Запомнить меня
            </label>
          </div>
        )}

        <button
          type="submit"
          disabled={loading}
          className={`w-full py-3 rounded-lg font-semibold transition-all duration-300 ${
            loading 
              ? 'bg-gray-400 cursor-not-allowed' 
              : 'bg-gold-600 hover:bg-gold-700 text-white shadow-lg hover:shadow-xl'
          }`}
        >
          {loading ? (
            <div className="flex items-center justify-center">
              <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white mr-3"></div>
              {isLogin ? 'Вход...' : 'Регистрация...'}
            </div>
          ) : (
            isLogin ? 'Войти в аккаунт' : 'Создать аккаунт'
          )}
        </button>
      </form>

      <div className="mt-6 text-center">
        <button
          type="button"
          onClick={switchMode}
          className="text-gold-600 hover:text-gold-700 font-medium transition-colors"
          disabled={loading}
        >
          {isLogin ? 'Нет аккаунта? Зарегистрироваться' : 'Уже есть аккаунт? Войти'}
        </button>
      </div>

      {/* Демо доступ */}
      <div className="mt-6 p-4 bg-gray-50 rounded-lg border">
        <h3 className="text-sm font-semibold mb-2 text-gray-700">Для тестирования:</h3>
        <div className="grid grid-cols-2 gap-3 text-xs">
          <div className="bg-white p-2 rounded border">
            <p className="font-medium text-gray-600">Email:</p>
            <p className="text-gray-800 font-mono">test@example.com</p>
          </div>
          <div className="bg-white p-2 rounded border">
            <p className="font-medium text-gray-600">Пароль:</p>
            <p className="text-gray-800 font-mono">123456</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Auth; // ЗДЕСЬ ОБЯЗАТЕЛЬНО ЗАКАНЧИВАЕТСЯ ФАЙЛ - УДАЛИТЕ ВСЁ ЧТО ПОСЛЕ ЭТОЙ СТРОКИ
